components.get.args:
位置参数数组：[input: {
    /** 需要读取或编辑该组件的节点身份列表；不同节点不共享组件实例。 */
    nodes: NodeHandle[];
    /** 组件字段键，必须来自当前 components.listTypes/schema；未知组件不能按猜测字段写入。 */
    type: string;
} & {
    /** 可选组件内部字段列表；与分页行投影不同，只接受该组件 schema 中的字段键，列表组件不支持。 */
    fields?: string[];
}, options?: {
    /** 请求的最大条数，必须为正安全整数，默认 100；不设置固定条数或单页字节数上限。 */
    limit?: number;
    /** 上一页的 nextCursor，原样传回；继续分页时保留同一目标、筛选和投影，编辑或查询变化后须从头读取。 */
    cursor?: string;
}]
args[0] input: 目标组件与可选组件内部字段投影；input.fields 不等同于行字段投影。
args[1] options: 可选分页选项；limit 默认为 100，须为正安全整数，无固定上限，cursor 原样延续同一查询，此方法不实现行字段投影。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

components.get.returns:
{
    /** 本页实际返回的记录，字段范围以请求投影为准；即使不足 limit，也应检查 nextCursor 是否仍有后续。 */
    items: {
        /** 本行组件值所属的节点身份，与请求节点对应。 */
        node: NodeHandle;
        /** 当前组件值；未投影且组件缺失时为 null，指定内部 fields 时返回包含实际存在字段的对象。 */
        values: JsonValue;
    }[];
    /** 是否仍有未返回的记录；为 true 时使用 nextCursor 继续读取，不表示场景或源码被截断保存。 */
    truncated: boolean;
    /** 存在后续记录时返回的游标；缺省表示已读完，不能解析、拼接或跨查询复用。 */
    nextCursor?: string;
}
节点与组件值分页；未投影且组件不存在时为 null。
fields 投影组件内部字段；未投影且组件不存在时返回 null。
类型约定：
JsonValue：可穿过 SDK 调用边界的 JSON 数据；不允许函数、undefined 或宿主对象。
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

components.set.args:
位置参数数组：[input: {
    /** 需要读取或编辑该组件的节点身份列表；不同节点不共享组件实例。 */
    nodes: NodeHandle[];
    /** 组件字段键，必须来自当前 components.listTypes/schema；未知组件不能按猜测字段写入。 */
    type: string;
} & {
    /** 要写入的顶层字段对象或整个组件列表；未指定对象字段保持原值，嵌套对象与数组整体替换。 */
    values?: JsonObject | JsonValue[];
    /** 可选 JSON Pointer 删除路径列表；仅对象组件支持，不能删除 schema 必填字段或与其它操作路径重叠。 */
    unset?: string[];
    /** 可选 JSON Pointer 重置路径列表；已知 schema 下恢复已验证默认值，无默认值时删除可选字段；必填字段无默认值或 schema 未知则拒绝。列表组件不支持逐项 reset。 */
    reset?: string[];
}]
args[0] input: 目标组件及 values/unset/reset；嵌套对象和数组整体替换，列表组件不能逐项 patch。
类型约定：
JsonValue：可穿过 SDK 调用边界的 JSON 数据；不允许函数、undefined 或宿主对象。
JsonObject：动态组件与脚本参数的 JSON 对象；字段规则由当前 schema 决定。
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

transforms.get.args:
位置参数数组：[input: {
    /** 要读取的节点身份列表；当前文档中不存在的句柄会报错，不按显示名查找。 */
    nodes: NodeHandle[];
    /** 读取空间：world 返回世界位置/旋转及有符号 lossyScale，local 返回相对父节点的 TRS。 */
    space: "world" | "local";
}]
args[0] input: 目标节点与读取空间；world/local 含义见字段，所有返回值使用同一所选空间。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。

transforms.get.returns:
Array<{
    /** 本条变换所属节点的原身份，可与请求列表对应。 */
    node: NodeHandle;
    /** 所请求空间中的完整 TRS；字段不可当作原始保存 DTO 的混合坐标直接写回。 */
    transform: {
        /** 所选 space 中的位置，单位为米；local 相对于父节点，world 相对于世界原点。 */
        position: {
            /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            x: number;
            /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
            y: number;
            /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            z: number;
        };
        /** 所选 space 中的单位四元数，分量顺序为 xyzw；不能传欧拉角。 */
        rotation: {
            /** 四元数向量部分的 X 分量，无单位；与 y/z/w 共同构成归一化旋转，不是以米为单位的位置。 */
            x: number;
            /** 四元数向量部分的 Y 分量，无单位；表示旋转分量，不是欧拉角或 Y 轴平移。 */
            y: number;
            /** 四元数向量部分的 Z 分量，无单位；必须与其它分量一起有限且归一化。 */
            z: number;
            /** 单位四元数的标量分量；与 x/y/z 一起满足归一化约束，单位旋转为 {x:0,y:0,z:0,w:1}。 */
            w: number;
        };
        /** 所选 space 中的缩放，无单位；local 为局部缩放，world 为有符号 lossyScale，分量不能为零。 */
        scale: {
            /** X 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            x: number;
            /** Y 分量，必须为有限数；Unity 的向上轴为 Y，位置/平移使用米，缩放使用无单位倍率。 */
            y: number;
            /** Z 分量，必须为有限数；位置/平移使用米，缩放使用无单位倍率，作为缩放时不能为零。 */
            z: number;
        };
    };
}>
每个指定节点在所选空间的完整 TRS，world 缩放为有符号 lossyScale。
读取所有指定节点的变换；world 缩放使用有符号 lossyScale。
类型约定：
NodeHandle：当前文档中的节点身份；文档 ID 不变则句柄不变，ID 复用后定位新节点。
WPrefab 宿主返回 n12，直接来自文档 node.id；目标由外层操作选择，不是 Unity GetInstanceID()。
